import { Download, ExternalLink } from 'lucide-react';
import type { Metadata } from 'next';
import { getTranslations } from 'next-intl/server';
import { buttonVariants } from '@/components/ui/button-variants';
import { initRequestLocale } from '@/i18n/server';
import { myParticipation, myVendor } from '@/lib/catalogue/server';
import { storefrontUrl } from '@/lib/storefront/qr';
import { currentApplicationEvent } from '@/lib/vendor/server';
import { NoVendor } from '../products/no-vendor';

export const metadata: Metadata = { robots: { index: false } };

/** The vendor's QR code and printable table sign (QR-01). */
export default async function VendorQrPage({ params }: PageProps<'/[locale]/vendor/qr'>) {
  initRequestLocale((await params).locale);
  const t = await getTranslations('VendorQr');
  const vendor = await myVendor();
  if (!vendor) return <NoVendor title={t('title')} />;
  const event = await currentApplicationEvent();
  const participation = event ? await myParticipation(vendor.id, event.id) : null;
  if (!event || participation?.status !== 'approved') {
    return (
      <div className="mx-auto grid w-full max-w-3xl gap-6">
        <h1 className="font-display text-display-md font-semibold">{t('title')}</h1>
        <p className="rounded-xl border border-border bg-card p-6 text-body text-muted-foreground">
          {t('notApproved')}
        </p>
      </div>
    );
  }
  const url = storefrontUrl(event.slug, vendor.slug);
  const live = vendor.profile_published && participation.is_published;

  return (
    <div className="mx-auto grid w-full max-w-3xl gap-6">
      <header className="grid gap-1">
        <p className="text-body-sm font-semibold text-primary">{event.name}</p>
        <h1 className="font-display text-display-md font-semibold">{t('title')}</h1>
        <p className="max-w-prose text-body text-muted-foreground">{t('intro')}</p>
      </header>
      {!live && (
        <p
          role="status"
          className="rounded-lg bg-warning-subtle p-4 text-body-sm text-warning-subtle-foreground"
        >
          {t('notPublished')}
        </p>
      )}
      <section className="grid gap-6 rounded-xl border border-border bg-card p-6 sm:grid-cols-[14rem_minmax(0,1fr)] sm:items-center">
        {/* eslint-disable-next-line @next/next/no-img-element -- generated by our own route */}
        <img
          src="/api/vendor/qr/png"
          alt={t('alt', { url })}
          width={224}
          height={224}
          className="size-56 bg-card rounded-lg border border-border p-2"
        />
        <div className="grid content-start gap-4">
          <div className="grid gap-1">
            <p className="text-body-sm font-medium text-muted-foreground">{t('url')}</p>
            <p className="font-mono text-body-sm break-all" data-testid="storefront-url">
              {url}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
            <a href="/api/vendor/qr/pdf" download className={buttonVariants()}>
              <Download aria-hidden />
              {t('pdf')}
            </a>
            <a
              href="/api/vendor/qr/png"
              download
              className={buttonVariants({ variant: 'outline' })}
            >
              <Download aria-hidden />
              {t('png')}
            </a>
            <a
              href={url}
              target="_blank"
              rel="noopener"
              className={buttonVariants({ variant: 'ghost' })}
            >
              <ExternalLink aria-hidden />
              {t('open')}
            </a>
          </div>
        </div>
      </section>
    </div>
  );
}
